#!/bin/bash
set -euo pipefail
mkdir -p "$(dirname /app/INTEGRATION.json)"
base64 -d > /app/INTEGRATION.json <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/ball_physics.ts)"
base64 -d > /app/src/sim/ball_physics.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/ball_state.ts)"
base64 -d > /app/src/sim/ball_state.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/first_touch.ts)"
base64 -d > /app/src/sim/first_touch.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/input_provider.ts)"
base64 -d > /app/src/sim/input_provider.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/kick.ts)"
base64 -d > /app/src/sim/kick.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/locomotion.ts)"
base64 -d > /app/src/sim/locomotion.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/match_log.ts)"
base64 -d > /app/src/sim/match_log.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/match_sim.ts)"
base64 -d > /app/src/sim/match_sim.ts <<'MB_ORACLE'

MB_ORACLE
mkdir -p "$(dirname /app/src/sim/player_state.ts)"
base64 -d > /app/src/sim/player_state.ts <<'MB_ORACLE'

MB_ORACLE
